var NL=String.fromCharCode(10);
const allCalendarItems = $('📅 Google Calendar - I dag').all();
const now = new Date();
const today = new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Copenhagen',year:'numeric',month:'2-digit',day:'2-digit'}).format(now);
const todayLabel = new Intl.DateTimeFormat('da-DK',{timeZone:'Europe/Copenhagen',weekday:'long',year:'numeric',month:'long',day:'numeric'}).format(now);
function hm(dt){ return new Date(dt).toLocaleTimeString('da-DK',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Copenhagen'}); }
const calendarItems = allCalendarItems.map(function(i){return i.json;}).filter(function(e){ var d=e.start && (e.start.dateTime||e.start.date); if(!d) return false; return String(d).slice(0,10)===today; });
var events = calendarItems.length ? calendarItems.map(function(e){ var t=e.start.dateTime?hm(e.start.dateTime):'Hele dagen'; return '• '+t+': '+(e.summary||'Ingen titel'); }).join(NL) : '• Ingen kalenderbegivenheder i dag';
const systemPrompt = [
'Du er Daniels personlige aftenassistent. Du er varm, reflekterende og motiverende.',
'',
'Skriv ALTID korrekt dansk med æ, ø og å. Brug rigtige danske bogstaver — aldrig ae/oe/aa.',
'',
'Giv en aftenbriefing der opsummerer dagen og motiverer til en god start på morgen.',
'',
'Format (Telegram Markdown — brug *fed*):',
'',
'🌙 *God aften, Daniel*',
'[En varm, personlig hilsen — maks 1 sætning]',
'',
'✅ *Hvad du opnåede i dag*',
'[Opsummer konkret ud fra kalenderen. Vær specifik og anerkendende.]',
'',
'💪 *Motivationsboost*',
'[2-3 sætninger der anerkender indsatsen og motiverer til i morgen.]',
'',
'🌱 *En tanke til i morgen*',
'[Et konkret fokuspunkt]',
'',
'⏱️ *Tidsfeedback til din assistent*',
'Svar på denne besked med hvor lang tid dagens opgaver faktisk tog (fx: kampagne 2t, mails 30 min), så finjusterer jeg dine fremtidige estimater.',
'',
'📚 *Læring*',
'[En anbefaling inden for AI/tech eller studie]',
'',
'Gengiv afsnittet Tidsfeedback ordret. Maks 350 ord. Undgå KUN ubalancerede Markdown-styringstegn (* _ ` [ ]) — brug ALTID korrekte danske bogstaver æ ø å.'
].join(NL);
const userContent = 'Dato: '+todayLabel+NL+NL+'Kalenderbegivenheder i dag:'+NL+events;
return [{ json: { payload: JSON.stringify({ model:'claude-sonnet-4-6', max_tokens:1200, system: systemPrompt, messages:[{ role:'user', content: userContent }] }) } }];
